    end = time_to_minutes(event["end"])
    if start >= end:
        raise ValueError(f"Event start {event['start']} must be before end {event['end']}")


def suggest_slots(events: List[Dict[str, str]], meeting_duration: int, day: str) -> List[str]:
    if (not isinstance(meeting_duration, int)
            or isinstance(meeting_duration, bool)
            or meeting_duration <= 0):
        raise ValueError("Meeting duration must be a positive integer")

    try:
        datetime.strptime(day, "%Y-%m-%d")
    except Exception:
        raise ValueError(f"Invalid date: {day}")

    work_start = time_to_minutes(WORK_START)
    work_end = time_to_minutes(WORK_END)

    if meeting_duration > (work_end - work_start):
        return []

    # Normalize and merge events, including overlaps and back-to-back events.
    busy_times = []
    for event in events:
        validate_event(event)
        start = max(work_start, time_to_minutes(event["start"]))
        end = min(work_end, time_to_minutes(event["end"]))
        if start < end:
            busy_times.append((start, end))

    busy_times.sort()
    merged = []
    for start, end in busy_times:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)

    # Enumerate every minute at which the entire meeting fits in a free gap.
    slots = []
    prev_end = work_start
    for start, end in merged:
        slots.extend(
            minutes_to_time(slot_start)
            for slot_start in range(prev_end, start - meeting_duration + 1)
        )
        prev_end = end

    slots.extend(
        minutes_to_time(slot_start)
        for slot_start in range(prev_end, work_end - meeting_duration + 1)
    )
    return slots
